package com.atskolla.teacher;
import android.Manifest;import android.app.*;import android.content.*;import android.content.pm.PackageManager;import android.graphics.*;import android.hardware.Camera;import android.os.*;import android.view.*;import android.widget.*;import com.google.zxing.*;import com.google.zxing.common.HybridBinarizer;import java.io.*;import java.util.*;import java.util.concurrent.*;import static com.atskolla.teacher.Ui.*;

/** Native camera capture + ZXing. Photos remain private and are removed after face verification. */
@SuppressWarnings("deprecation")
public final class ScannerActivity extends Activity implements SurfaceHolder.Callback {
 Camera camera;SurfaceView surface;TextView hint;boolean face,busy,closed,front;long lastFrame;ExecutorService decoder=Executors.newSingleThreadExecutor();Handler main=new Handler(Looper.getMainLooper());
 @Override public void onCreate(Bundle state){super.onCreate(state);face="face".equals(getIntent().getStringExtra("mode"));LinearLayout page=column(this);pad(page,16);page.setPadding(dp(this,16),dp(this,40),dp(this,16),dp(this,24));page.setBackgroundColor(BG);page.addView(text(this,face?"Pengenalan Wajah":"Pindai QR / Barcode",22,INK,true));gap(page,10);hint=text(this,face?"Posisikan satu wajah dengan pencahayaan yang cukup.":"Arahkan kamera ke kartu siswa atau guru.",13,MUTED,false);page.addView(hint);gap(page,16);surface=new SurfaceView(this);page.addView(surface,new LinearLayout.LayoutParams(-1,0,1));gap(page,12);if(face)page.addView(button(this,"Ambil foto & kenali wajah",true,this::capture),new LinearLayout.LayoutParams(-1,dp(this,48)));gap(page,8);page.addView(button(this,"Kembali",false,this::finish),new LinearLayout.LayoutParams(-1,dp(this,48)));setContentView(page);surface.getHolder().addCallback(this);if(checkSelfPermission(Manifest.permission.CAMERA)!=PackageManager.PERMISSION_GRANTED)requestPermissions(new String[]{Manifest.permission.CAMERA},410);}
 @Override public void onRequestPermissionsResult(int req,String[] permissions,int[] results){super.onRequestPermissionsResult(req,permissions,results);if(req==410){if(results.length>0&&results[0]==PackageManager.PERMISSION_GRANTED)open();else hint.setText("Izin kamera ditolak. Kembali dan gunakan input kode / RFID.");}}
 @Override public void surfaceCreated(SurfaceHolder holder){open();}@Override public void surfaceChanged(SurfaceHolder h,int f,int w,int height){}@Override public void surfaceDestroyed(SurfaceHolder holder){release();}
 void open(){if(camera!=null||closed||!surface.getHolder().getSurface().isValid()||checkSelfPermission(Manifest.permission.CAMERA)!=PackageManager.PERMISSION_GRANTED)return;try{int selected=0;for(int i=0;i<Camera.getNumberOfCameras();i++){Camera.CameraInfo info=new Camera.CameraInfo();Camera.getCameraInfo(i,info);if(info.facing==(face?Camera.CameraInfo.CAMERA_FACING_FRONT:Camera.CameraInfo.CAMERA_FACING_BACK)){selected=i;break;}}Camera.CameraInfo info=new Camera.CameraInfo();Camera.getCameraInfo(selected,info);front=info.facing==Camera.CameraInfo.CAMERA_FACING_FRONT;camera=Camera.open(selected);Camera.Parameters p=camera.getParameters();Camera.Size best=p.getSupportedPreviewSizes().get(0);for(Camera.Size size:p.getSupportedPreviewSizes())if(size.width<=800&&size.width>=640){best=size;break;}p.setPreviewSize(best.width,best.height);p.setPreviewFormat(ImageFormat.NV21);List<String> focus=p.getSupportedFocusModes();if(focus!=null&&focus.contains(Camera.Parameters.FOCUS_MODE_CONTINUOUS_PICTURE))p.setFocusMode(Camera.Parameters.FOCUS_MODE_CONTINUOUS_PICTURE);Camera.Size small=p.getSupportedPictureSizes().get(0);for(Camera.Size size:p.getSupportedPictureSizes())if(size.width>=640&&size.width<=1280){small=size;break;}p.setPictureSize(small.width,small.height);p.setJpegQuality(75);p.setRotation(90);camera.setParameters(p);int rotation=getWindowManager().getDefaultDisplay().getRotation()*90;int orientation=front?(360-(info.orientation+rotation)%360)%360:(info.orientation-rotation+360)%360;camera.setDisplayOrientation(orientation);camera.setPreviewDisplay(surface.getHolder());if(!face)camera.setPreviewCallback((bytes,c)->frame(bytes,c.getParameters().getPreviewSize()));camera.startPreview();}catch(Exception e){release();hint.setText("Kamera belum tersedia. Gunakan kolom kode atau periksa izin kamera.");}}
 void frame(byte[] data,Camera.Size size){if(busy||closed||System.currentTimeMillis()-lastFrame<300)return;busy=true;lastFrame=System.currentTimeMillis();decoder.execute(()->{try{MultiFormatReader reader=new MultiFormatReader();reader.setHints(Collections.singletonMap(DecodeHintType.POSSIBLE_FORMATS,Arrays.asList(BarcodeFormat.QR_CODE,BarcodeFormat.CODE_128,BarcodeFormat.CODE_39,BarcodeFormat.EAN_13,BarcodeFormat.ITF)));Result found;try{found=reader.decodeWithState(new BinaryBitmap(new HybridBinarizer(new PlanarYUVLuminanceSource(data,size.width,size.height,0,0,size.width,size.height,false))));}catch(NotFoundException e){byte[] rotated=new byte[size.width*size.height];for(int y=0;y<size.height;y++)for(int x=0;x<size.width;x++)rotated[x*size.height+size.height-y-1]=data[y*size.width+x];found=reader.decodeWithState(new BinaryBitmap(new HybridBinarizer(new PlanarYUVLuminanceSource(rotated,size.height,size.width,0,0,size.height,size.width,false))));}String text=found.getText();main.post(()->{if(!closed){closed=true;setResult(RESULT_OK,new Intent().putExtra("code",text));finish();}});}catch(Exception ignored){}finally{busy=false;}});}
 void capture(){if(camera==null||busy)return;busy=true;hint.setText("Mengambil foto…");try{camera.takePicture(null,null,(jpeg,c)->decoder.execute(()->{try{BitmapFactory.Options opts=new BitmapFactory.Options();opts.inSampleSize=2;Bitmap photo=BitmapFactory.decodeByteArray(jpeg,0,jpeg.length,opts);if(photo==null)throw new IOException();float scale=Math.min(1,640f/Math.max(photo.getWidth(),photo.getHeight()));Bitmap reduced=Bitmap.createScaledBitmap(photo,Math.max(1,Math.round(photo.getWidth()*scale)),Math.max(1,Math.round(photo.getHeight()*scale)),true);File target=new File(getCacheDir(),"face-capture.jpg");try(FileOutputStream out=new FileOutputStream(target)){reduced.compress(Bitmap.CompressFormat.JPEG,75,out);}if(reduced!=photo)reduced.recycle();photo.recycle();main.post(()->{if(!closed){setResult(RESULT_OK,new Intent().putExtra("photo",target.getAbsolutePath()));finish();}});}catch(Exception | OutOfMemoryError e){main.post(()->{busy=false;hint.setText("Foto belum dapat diambil. Coba kembali.");try{if(camera!=null)camera.startPreview();}catch(Exception ignored){}});}}));}catch(Exception e){busy=false;hint.setText("Kamera belum siap. Coba kembali.");}}
 void release(){if(camera!=null){try{camera.setPreviewCallback(null);camera.stopPreview();camera.release();}catch(Exception ignored){}camera=null;}}
 @Override protected void onPause(){release();super.onPause();}@Override protected void onResume(){super.onResume();if(surface!=null)open();}@Override protected void onDestroy(){closed=true;release();decoder.shutdownNow();main.removeCallbacksAndMessages(null);super.onDestroy();}
}
